import mongoose from "mongoose";

const inventorySchema = new mongoose.Schema(
  {
    product: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Product",
      required: true,
      index: true,
    },
    // Unique lot reference generated by the inventory service when omitted.
    batch: { type: String, required: true, trim: true },
    // Remaining quantity in this physical batch. New records never go negative.
    quantity: {
      type: Number,
      required: true,
      min: [0, "Batch quantity cannot be negative"],
      validate: {
        validator: Number.isSafeInteger,
        message: "Batch quantity must be a whole number.",
      },
    },
    // Integer kobo. Null means the acquisition cost is unknown.
    unitCost: {
      type: Number,
      default: null,
      min: [0, "Unit cost cannot be negative"],
      validate: {
        validator: (value) => value == null || Number.isSafeInteger(value),
        message: "Unit cost must be stored as integer kobo.",
      },
    },
    receivedDate: { type: Date, default: Date.now, index: true },
    supplier: { type: String, trim: true, default: "" },
    location: { type: String, trim: true, default: "" },
    isActive: { type: Boolean, default: true, index: true },
    createdBy: { type: mongoose.Schema.Types.ObjectId, ref: "User", index: true },
    updatedBy: { type: mongoose.Schema.Types.ObjectId, ref: "User", index: true },
    source: {
      type: String,
      enum: ["restock", "order", "adjust", "damaged", "return", "void"],
      default: "restock",
      index: true,
    },
    reason: { type: String, trim: true, default: "" },
  },
  { timestamps: true }
);

inventorySchema.index({ product: 1, receivedDate: 1, createdAt: 1 });
inventorySchema.index({ product: 1, isActive: 1, quantity: 1 });
inventorySchema.index({ source: 1, createdAt: -1 });
inventorySchema.index({ product: 1, batch: 1 });

export default mongoose.model("Inventory", inventorySchema);
